import importlib
from pathlib import Path
import re
import subprocess
from userlib import core

samples = [
    {'first': 'Ada', 'last': 'Lovelace'},
    {'first': '', 'last': ''},
    {'first': 'José', 'last': 'Silva'},
    {},
    {'first': 'Ada'},
    {'first': None, 'last': 'Lovelace'},
]

def outcome(function, user):
    try:
        return ('return', function(user))
    except Exception as error:
        return ('raise', type(error), error.args)

baseline = {}
original_core = subprocess.check_output(['git', 'show', 'HEAD:userlib/core.py'], text=True)
exec(compile(original_core, 'baseline/core.py', 'exec'), baseline)
for user in samples:
    assert outcome(core.fetch_user_name, user) == outcome(baseline['get_user_name'], user)
    assert outcome(core.get_user_name_legacy, user) == outcome(baseline['get_user_name_legacy'], user)

for index in range(8):
    module = importlib.import_module(f'userlib.feature_{index}')
    original = subprocess.check_output(['git', 'show', f'HEAD:userlib/feature_{index}.py'], text=True)
    namespace = dict(baseline)
    exec(compile(original.replace('from userlib.core import get_user_name, get_user_name_legacy\\n', ''), f'baseline/feature_{index}.py', 'exec'), namespace)
    for user in samples:
        assert outcome(module.label, user) == outcome(namespace['label'], user)

for path in Path('userlib').glob('*.py'):
    original = subprocess.check_output(['git', 'show', f'HEAD:{path.as_posix()}'], text=True)
    expected = re.sub(r'\\bget_user_name\\b', 'fetch_user_name', original)
    assert path.read_text() == expected, path
    assert not re.search(r'\\bget_user_name\\b', path.read_text()), path
print('Passed: core functions and all 8 feature modules preserve outputs and errors; only the requested identifier changed.')
